// Cache-aside with TTL jitter and write-invalidation (Node.js / ioredis)
import { Redis } from 'ioredis';
const redis = new Redis(process.env.REDIS_URL);

const BASE_TTL = 300; // 5 minutes base

// Add ±10% jitter to prevent thundering herd on mass expiry
function jitteredTTL(base) {
  const jitter = Math.floor(base * 0.1 * Math.random());
  return base + jitter;
}

// READ — cache-aside lazy loading
async function getProduct(id) {
  const key = `product:${id}`;

  const cached = await redis.get(key);
  if (cached !== null) {
    return JSON.parse(cached); // cache HIT: ~0.5ms round-trip
  }

  // Cache MISS: query source of truth
  const row = await db.query(
    'SELECT * FROM products WHERE id = $1 AND deleted_at IS NULL',
    [id]
  );

  if (row) {
    // SETEX is atomic: set value AND TTL in one command.
    // Never use SET then EXPIRE — a crash between the two leaves
    // a key with no TTL that persists forever.
    await redis.setex(key, jitteredTTL(BASE_TTL), JSON.stringify(row));
  }

  return row; // ~20ms DB latency on miss, but cache warm for next requests
}

// WRITE — invalidate on mutation
async function updateProductPrice(id, newPrice) {
  // Always write source of truth first
  await db.query(
    'UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2',
    [newPrice, id]
  );
  // Then invalidate cache — next read re-populates with fresh data
  await redis.del(`product:${id}`);
  // Alternative: redis.setex(key, TTL, JSON.stringify(updated)) — write-through
  // But del is simpler and avoids stale-serialisation bugs
}

// CDN-facing HTTP endpoint
app.get('/api/public/products', async (req, res) => {
  const products = await getProductList();
  res
    // 'public': CDN and shared caches may store this response
    // max-age=60: serve from CDN cache for up to 60 seconds
    // stale-while-revalidate=30: after max-age, serve stale for 30s
    //   while asynchronously fetching fresh from origin
    .set('Cache-Control', 'public, max-age=60, stale-while-revalidate=30')
    .json(products);
});

// HTTP cache header patterns in an Express.js API

// 1. PUBLIC CONTENT — cacheable at CDN and browser
// Product listing page — public, CDN caches 5 min, browser 1 min
app.get('/api/products', async (req, res) => {
  const products = await getProductsWithCache();
  res
    .set('Cache-Control', 'public, max-age=60, s-maxage=300, stale-while-revalidate=60')
    // ETag enables conditional requests: browser sends If-None-Match on revalidation
    .set('ETag', computeETag(products))
    .json(products);
});

// 2. PRIVATE CONTENT — only browser may cache, never CDN
// User account page — private, short TTL
app.get('/api/user/profile', authenticate, async (req, res) => {
  const profile = await getUserProfile(req.user.id);
  res
    .set('Cache-Control', 'private, max-age=300')
    .json(profile);
});

// 3. SENSITIVE — no caching anywhere
// Payment/financial data
app.get('/api/user/payment-methods', authenticate, async (req, res) => {
  const methods = await getPaymentMethods(req.user.id);
  res
    .set('Cache-Control', 'no-store')
    .json(methods);
});

// 4. VERSIONED STATIC ASSET — effectively immutable
// Served by CDN; URL changes when content changes (content hashing via Vite/Webpack)
app.use('/static', express.static('dist', {
  setHeaders: (res, path) => {
    if (path.match(/\.[a-f0-9]{8}\.(js|css|woff2)$/)) {
      // Hash in filename guarantees new URL on new content — safe to cache forever
      res.set('Cache-Control', 'public, max-age=31536000, immutable');
    } else {
      // Non-hashed files (favicon.ico, robots.txt) — cache for 1 day
      res.set('Cache-Control', 'public, max-age=86400');
    }
  }
}));

// 5. CDN PURGE — invalidate edge cache after deploy or content update
// Using Cloudflare API as example
async function purgeEdgeCache(paths) {
  await fetch(
    `https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/purge_cache`,
    {
      method: 'POST',
      headers: { Authorization: `Bearer ${CF_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ files: paths }),
    }
  );
}

// Thundering herd prevention: mutex with stale-value fallback
// Uses Redis SET NX (atomic acquire) pattern

async function getWithMutex(key, fetchFn, ttl = 300) {
  // 1. Try fast path: cache hit
  const cached = await redis.get(key);
  if (cached !== null) return JSON.parse(cached);

  // 2. Cache miss — try to acquire a distributed lock
  const lockKey = `lock:${key}`;
  const lockTTL = 10; // safety expiry in case the lock holder crashes
  const acquired = await redis.set(lockKey, '1', 'NX', 'EX', lockTTL);

  if (acquired === 'OK') {
    // 3. We hold the lock — fetch fresh data
    try {
      const fresh = await fetchFn();
      await redis.setex(key, jitteredTTL(ttl), JSON.stringify(fresh));
      return fresh;
    } finally {
      await redis.del(lockKey); // always release the lock
    }
  } else {
    // 4. Another process is fetching — wait briefly, then return stale or retry
    await new Promise(r => setTimeout(r, 100));
    const retried = await redis.get(key);
    if (retried !== null) return JSON.parse(retried);
    // Last resort: fetch directly (rare — only if lock holder was very slow)
    return fetchFn();
  }
}

// Usage
const products = await getWithMutex(
  'products:featured',
  () => db.query('SELECT * FROM products WHERE featured = true'),
  300
);

// XFetch: probabilistic early expiry
// Regenerate before TTL with probability proportional to proximity to expiry
async function getWithEarlyExpiry(key, fetchFn, ttl) {
  const cached = await redis.get(key);
  const remaining = await redis.ttl(key); // seconds until expiry

  if (cached !== null) {
    // Probability of early refresh increases as remaining TTL decreases
    const beta = 1.0; // tuning parameter
    const shouldRefresh = Math.random() * ttl < beta * Math.log(ttl / remaining);

    if (!shouldRefresh) return JSON.parse(cached); // serve cached
  }

  // Fetch fresh and update cache
  const fresh = await fetchFn();
  await redis.setex(key, jitteredTTL(ttl), JSON.stringify(fresh));
  return fresh;
}
